{
  "themes": [
    {
      "cluster": 12,
      "name": "iCloud Photo Deletion Delays",
      "description": "Customers report photos remain in iCloud or disappear unexpectedly after deleting them on their iPhone."
    },
    {
      "cluster": 13,
      "name": "Apple ID Phishing Emails",
      "description": "Users receive suspicious emails claiming to be from Apple and seek verification if they are scams."
    },
    {
      "cluster": 14,
      "name": "Podcast App Auto‑Play & Queue Issues",
      "description": "After updates, episodes stop auto‑playing, reappear after deletion, and the queue is hard to locate."
    },
    {
      "cluster": 15,
      "name": "iPhone Pre‑Order Confirmation Problems",
      "description": "Buyers cannot find order confirmations, see mismatched order numbers, or cannot cancel pre‑orders."
    },
    {
      "cluster": 16,
      "name": "Missing or Delayed Customer Support Calls",
      "description": "Customers complain about not receiving scheduled support calls or lacking a chat option."
    },
    {
      "cluster": 17,
      "name": "Unexpected Emoji/Character Glitches",
      "description": "New emojis appear incorrectly or random question‑mark boxes replace characters after updates."
    },
    {
      "cluster": 18,
      "name": "Boxed Question‑Mark Glyphs After Update",
      "description": "Users see small boxes with question marks in place of text following iOS updates."
    },
    {
      "cluster": 19,
      "name": "Battery Health Check Requests",
      "description": "Customers ask how to view battery health on iPhone/iPad without visiting a store."
    },
    {
      "cluster": 20,
      "name": "Apple Pay Functionality Issues",
      "description": "Users experience Apple Pay not working, regional availability questions, and device‑specific usage problems."
    },
    {
      "cluster": 21,
      "name": "Question‑Mark Box Rendering Bugs",
      "description": "Repeated reports of question‑mark boxes appearing in text after system updates."
    },
    {
      "cluster": 22,
      "name": "Persistent Question‑Mark Glyphs Post‑Update",
      "description": "Even after days, users still see question‑mark boxes in place of characters on updated devices."
    },
    {
      "cluster": 23,
      "name": "Payment Method Restrictions for Free Apps",
      "description": "Customers are frustrated that a credit card is required to download free apps and cannot update payment info after iOS updates."
    }
  ]
}
